1	package indexroom
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"strings"
14		"sync/atomic"
15	)
16	
17	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
18	// size, a malformed cursor, a cursor issued by another index instance, or
19	// continuation conditions that differ from the first page. It never reports
20	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
21	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
22	
23	// ErrQueryChanged marks a continuation whose pinned range no longer matches
24	// the first page: a block in the range was replaced (even under the same
25	// hash, and even if only its timestamp changed) or the chain was shortened
26	// below the pinned upper bound. No results are returned; the caller must
27	// restart from a first-page query.
28	var ErrQueryChanged = errors.New("indexroom: query data changed")
29	
30	// queryTxsHookLocked is a test-only rendezvous invoked once per QueryTxs
31	// call while index.mu is held: for a first page after the tip-bound height has
32	// been resolved (and non-empty ranges only), and for a continuation only after
33	// every pinned-range check has passed, so the call is committed to a
34	// successful page against the chain state in effect. It is nil in production;
35	// reorg regression tests park a query here to force a concurrent Reorg to wait
36	// (or park the Reorg and make the query wait), making the "one complete
37	// main-chain view per page" observation deterministic instead of relying on
38	// scheduling luck.
39	var queryTxsHookLocked func(from, to int64, continuation bool)
40	
41	const (
42		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
43		DefaultPageSize = 100
44		// MaxPageSize is the largest accepted TxQuery.PageSize.
45		MaxPageSize = 1000
46	)
47	
48	// TxQuery describes a transaction lookup against the main chain.
49	type TxQuery struct {
50		// From and To bound the searched heights, both inclusive. A zero From
51		// starts at height 1. A zero To pins the chain tip seen by the first
52		// page; an explicit To above the tip is clamped to it. Explicit heights
53		// must be positive, and an explicit To must not be below From.
54		From int64
55		To   int64
56		// TxIDs restricts results to these identifiers, matched by exact string
57		// comparison; an empty slice disables the filter. Duplicates and order
58		// inside the slice are irrelevant.
59		TxIDs []string
60		// PageSize picks the page length, 1..MaxPageSize; zero means
61		// DefaultPageSize. It may change between pages of the same query.
62		PageSize int
63		// Cursor continues an earlier query; empty asks for the first page. On
64		// continuation the height range and TxIDs must equal the first page's.
65		Cursor string
66	}
67	
68	// TxHit is one transaction occurrence on the main chain. The same
69	// identifier appears once per occurrence, in different blocks or several
70	// times inside one block.
71	type TxHit struct {
72		Height    int64
73		BlockHash string
74		TxID      string
75		Position  int
76	}
77	
78	// TxPage is one page of query results together with statistics over the
79	// whole filtered range. Hits are ordered by height, then by position inside
80	// the block.
81	type TxPage struct {
82		Hits []TxHit
83		// TotalMatches counts every matching occurrence in the pinned range; it
84		// does not change between pages of the same query.
85		TotalMatches int64
86		// MatchedBlocks counts the blocks holding at least one match.
87		MatchedBlocks int64
88		// ToHeight is the upper bound pinned by the first page: the requested
89		// To clamped to the chain tip seen at that moment.
90		ToHeight int64
91		// NextCursor continues the query; empty means this is the last page.
92		NextCursor string
93	}
94	
95	// QueryTxs searches the main chain for transaction occurrences matching the
96	// query. Every call observes one complete chain state: concurrent Append or
97	// Reorg calls never leak into a page, and the returned records are copies
98	// the caller may freely mutate. The query itself never modifies the index.
99	//
100	// The first page (empty Cursor) pins the filtered range and returns a
101	// continuation cursor while more results remain. Continuations reuse the
102	// pinned range — blocks appended above it are invisible to the query — and
103	// succeed as long as every block inside the range still matches the first
104	// page; otherwise they fail with ErrQueryChanged.
105	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
106		pageSize, err := normalizePageSize(query.PageSize)
107		if err != nil {
108			return TxPage{}, err
109		}
110		if query.Cursor != "" {
111			return index.continueQuery(query, pageSize)
112		}
113		return index.firstQuery(query, pageSize)
114	}
115	
116	func normalizePageSize(size int) (int, error) {
117		if size == 0 {
118			return DefaultPageSize, nil
119		}
120		if size < 0 || size > MaxPageSize {
121			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
122		}
123		return size, nil
124	}
125	
126	// normalizeRange validates the requested heights and resolves the zero From
127	// default. A zero To is left as-is; it is resolved against the chain tip
128	// while holding the lock.
129	func normalizeRange(from, to int64) (int64, int64, error) {
130		if from < 0 {
131			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
132		}
133		if to < 0 {
134			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
135		}
136		if from == 0 {
137			from = 1
138		}
139		if to != 0 && to < from {
140			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
141		}
142		return from, to, nil
143	}
144	
145	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
146		from, to, err := normalizeRange(query.From, query.To)
147		if err != nil {
148			return TxPage{}, err
149		}
150	
151		index.mu.Lock()
152		defer index.mu.Unlock()
153	
154		if to == 0 || to > index.Tip {
155			to = index.Tip
156		}
157		page := TxPage{Hits: []TxHit{}, ToHeight: to}
158		if from > to {
159			// Empty index or a start above the tip: a successful empty result.
160			return page, nil
161		}
162		if queryTxsHookLocked != nil {
163			queryTxsHookLocked(from, to, false)
164		}
165		filter := newTxFilter(query.TxIDs)
166		hits, total, blocks := index.scanPageLocked(from, to, filter, 0, pageSize)
167		return index.buildPageLocked(query.To, filter, from, to, hits, total, blocks, 0, pageSize), nil
168	}
