187		// added, removed, or replaced identifier rejects the continuation before
188		// the chain is examined.
189		filter := newTxFilter(query.TxIDs)
190		if filter.hexDigest() != payload.Set {
191			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
192		}
193	
194		index.mu.Lock()
195		defer index.mu.Unlock()
196	
197		if index.Tip < payload.To {
198			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
199				ErrQueryChanged, index.Tip, payload.To)
200		}
201		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
202			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
203		}
204		if queryTxsHookLocked != nil {
205			queryTxsHookLocked(payload.From, payload.To, true)
206		}
207		// Re-scan the still-identical pinned range: the cursor records the
208		// absolute offset, but no full match list is kept between pages.
209		hits, total, blocks := index.scanPageLocked(payload.From, payload.To, filter, payload.Off, pageSize)
210		if payload.Off > total {
211			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
212		}
213		return index.buildPageLocked(query.To, filter, payload.From, payload.To, hits, total, blocks, payload.Off, pageSize), nil
214	}
215	
216	// buildPageLocked assembles one page from a page-sized scan and mints the
217	// continuation cursor when matches remain. total and blocks describe the
218	// whole pinned range; hits holds only the window [offset, offset+pageSize).
219	// reqTo is the caller's verbatim To (zero for tip-bound queries). The caller
220	// must hold index.mu.
221	func (index *Index) buildPageLocked(reqTo int64, filter txFilter, from, to int64, hits []TxHit, total, blocks, offset int64, pageSize int) TxPage {
222		page := TxPage{
223			Hits:          hits,
224			TotalMatches:  total,
225			MatchedBlocks: blocks,
226			ToHeight:      to,
227		}
228		if offset+int64(len(hits)) < total {
229			page.NextCursor = index.encodeCursor(cursorPayload{
230				V:     1,
231				From:  from,
232				ReqTo: reqTo,
233				To:    to,
234				Set:   filter.hexDigest(),
235				FP:    hex.EncodeToString(index.fingerprintLocked(from, to)),
236				Off:   offset + int64(len(hits)),
237			})
238		}
239		return page
240	}
241	
242	// scanPageLocked walks the whole pinned range once in height/position order,
243	// counting every matching occurrence and every block holding one, while
244	// retaining only the page window [offset, offset+pageSize) in a pre-sized
245	// slice: at most pageSize TxHit records, independent of how many matches the
246	// whole range holds. The caller must hold index.mu.
247	func (index *Index) scanPageLocked(from, to int64, filter txFilter, offset int64, pageSize int) (hits []TxHit, total, blocks int64) {
248		hits = make([]TxHit, 0, pageSize)
249		for height := from; height <= to; height++ {
250			block := index.Blocks[height]
251			matched := false
252			for position, tx := range block.Txs {
253				if !filter.matches(tx) {
254					continue
255				}
256				if total >= offset && int64(len(hits)) < int64(pageSize) {
257					hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
258				}
259				total++
260				matched = true
261			}
262			if matched {
263				blocks++
264			}
265		}
266		return hits, total, blocks
267	}
268	
269	// fingerprintLocked hashes the exact content of every block in [from, to]:
270	// height, hash, parent, the ordered transaction list, and the timestamp
271	// (distinguishing a missing timestamp from zero). The caller must hold
272	// index.mu.
273	func (index *Index) fingerprintLocked(from, to int64) []byte {
274		h := sha256.New()
275		var lenBuf [8]byte
276		writeString := func(s string) {
277			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
278			h.Write(lenBuf[:])
279			h.Write([]byte(s))
280		}
281		for height := from; height <= to; height++ {
282			block := index.Blocks[height]
283			binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
284			h.Write(lenBuf[:])
285			writeString(block.Hash)
286			writeString(block.Parent)
287			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
288			h.Write(lenBuf[:])
289			for _, tx := range block.Txs {
290				writeString(tx)
291			}
292			if block.Time == nil {
293				h.Write([]byte{0})
294			} else {
295				h.Write([]byte{1})
296				binary.BigEndian.PutUint64(lenBuf[:], uint64(*block.Time))
297				h.Write(lenBuf[:])
298			}
299		}
300		return h.Sum(nil)
301	}
302	
303	// cursorPayload is the signed state carried between pages of one query.
304	type cursorPayload struct {
305		V     int    `json:"v"`
306		From  int64  `json:"from"`
307		ReqTo int64  `json:"reqTo"`
308		To    int64  `json:"to"`
309		Set   string `json:"set"`
310		FP    string `json:"fp"`
311		Off   int64  `json:"off"`
312	}
313	
314	const cursorPrefix = "q1"
315	
316	// encodeCursor serializes the payload and signs it with the per-instance
317	// key, so cursors are self-contained yet unusable on any other index.
318	func (index *Index) encodeCursor(payload cursorPayload) string {
